/**
 * GENERATED by web/scripts/gen-android-glyphs.mjs from
 * docs/design/system/assets/glyphs. Do not edit; run
 * `cd web && node scripts/gen-android-glyphs.mjs`.
 *
 * The fifty deity glyphs, one per culture per body, on the 24 x 24 grid they
 * were drawn on. Every path is the designer's, with its own stroke width, cap
 * and join; the generator rescales nothing.
 *
 * Fill and stroke are black so the caller's tint decides the colour, which is
 * how a received body takes the culture accent and the rest the bone ink
 * without a second set of vectors.
 *
 * Each glyph carries the honesty status the research settled: 28 attested,
 * 21 composed, 1 invented. [statusOf] reads it, and nothing in the app may
 * present a composed mark as attested.
 */
enum class GlyphStatus { ATTESTED, COMPOSED, INVENTED }

private val INK = SolidColor(Color.Black)

private fun glyph(name: String, paths: ImageVector.Builder.() -> Unit): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    ).apply(paths).build()

/** Built once each: a vector is immutable and the same instance redraws freely. */
private val cache = HashMap<Pair<AncientCulture, Planet>, ImageVector>()

/** The glyph [culture] draws for [body]. */
fun deityGlyph(culture: AncientCulture, body: Planet): ImageVector =
    cache.getOrPut(culture to body) { buildGlyph(culture, body) }

private fun buildGlyph(culture: AncientCulture, body: Planet): ImageVector =
    when (culture) {
        AncientCulture.EGYPT -> when (body) {
            Planet.SUN -> egyptSun()
            Planet.MOON -> egyptMoon()
            Planet.MERCURY -> egyptMercury()
            Planet.VENUS -> egyptVenus()
            Planet.MARS -> egyptMars()
            Planet.JUPITER -> egyptJupiter()
            Planet.SATURN -> egyptSaturn()
            Planet.URANUS -> egyptUranus()
            Planet.NEPTUNE -> egyptNeptune()
            Planet.PLUTO -> egyptPluto()
        }
        AncientCulture.GREECE -> when (body) {
            Planet.SUN -> greeceSun()
            Planet.MOON -> greeceMoon()
            Planet.MERCURY -> greeceMercury()
            Planet.VENUS -> greeceVenus()
            Planet.MARS -> greeceMars()
            Planet.JUPITER -> greeceJupiter()
            Planet.SATURN -> greeceSaturn()
            Planet.URANUS -> greeceUranus()
            Planet.NEPTUNE -> greeceNeptune()
            Planet.PLUTO -> greecePluto()
