        AncientCulture.CANAAN -> when (body) {
            Planet.SUN -> canaanSun()
            Planet.MOON -> canaanMoon()
            Planet.MERCURY -> canaanMercury()
            Planet.VENUS -> canaanVenus()
            Planet.MARS -> canaanMars()
            Planet.JUPITER -> canaanJupiter()
            Planet.SATURN -> canaanSaturn()
            Planet.URANUS -> canaanUranus()
