        AncientCulture.CARTHAGE -> when (body) {
            Planet.SUN -> carthageSun()
            Planet.MOON -> carthageMoon()
            Planet.MERCURY -> carthageMercury()
            Planet.VENUS -> carthageVenus()
            Planet.MARS -> carthageMars()
            Planet.JUPITER -> carthageJupiter()
            Planet.SATURN -> carthageSaturn()
            Planet.URANUS -> carthageUranus()
            Planet.NEPTUNE -> carthageNeptune()
            Planet.PLUTO -> carthagePluto()
        }
        AncientCulture.ROME -> when (body) {
            Planet.SUN -> romeSun()
            Planet.MOON -> romeMoon()
            Planet.MERCURY -> romeMercury()
